// Format a byte to hex at compile-time constant positions
Alpha::Uuid::UuidString formatUuid(const UuidBinary& binary) noexcept
{
   Alpha::Uuid::UuidString result{};

   // For the UUID structure
   size_t binaryIndex{0U};
   size_t resultIndex{0U};

   // Format each group in sequence
   for (size_t groupNum = 0U; groupNum < GROUP_COUNT; ++groupNum)
   {
      // Format all bytes in the current group
      for (size_t groupByte = 0U; groupByte < BYTES_PER_GROUP.at(groupNum); ++groupByte)
      {
         byteToHex(binary.at(binaryIndex), result.at(resultIndex), result.at(resultIndex + ONE));
         resultIndex += TWO;
         binaryIndex += ONE;
      }

      // Add hyphen after each group except the last one
      if (groupNum < (GROUP_COUNT - ONE))
      {
         result.at(resultIndex) = '-';
         resultIndex += ONE;
      }
   }

   return result;
}

