// Helper function to create SatellitePosition Polynomial
inline Polynomial<CLOCK_POLYNOMIAL_DEGREE, DIMENSION_1D> fillSatelliteClockPolynomials(
   const Time& referenceTime,
   const std::array<double, 5> oem7SatClockPoly,
   unsigned int inputDiscontinuityCounter = 0,
   double inputTimespanHalfValidity = 0.9)
{
   Polynomial<CLOCK_POLYNOMIAL_DEGREE, DIMENSION_1D> alphaSatClockPoly;
   alphaSatClockPoly.time = referenceTime;
   for (unsigned int order = 0; order < 5; ++order)
   {
      alphaSatClockPoly.data.coefficients.at(order).at(0)
         = oem7SatClockPoly.at(order) / POLYNOMIAL_FACTORIALS.at(order);
   }
   alphaSatClockPoly.data.discontinuityCounter = inputDiscontinuityCounter;
   alphaSatClockPoly.data.timespanHalfValidity = inputTimespanHalfValidity;
   return alphaSatClockPoly;
}

