      // populate optional and manditory header nodes based on the sub-type
      switch (headerRecord.getSubType())
      {
         case HlfRecordSubType::HeaderStartTime:
         case HlfRecordSubType::HeaderEndTime:
         case HlfRecordSubType::HeaderInputDescription:
         case HlfRecordSubType::HeaderRecordingInformation:
            static_cast<void>(HlfXmlSerializer::serializeHeader(m_mandatoryNode, headerRecord));
            break;
         case HlfRecordSubType::HeaderRecordingDescription:
         case HlfRecordSubType::HeaderApplicationConfiguration:
            static_cast<void>(HlfXmlSerializer::serializeHeader(m_optionalNode, headerRecord));
            break;
         case HlfRecordSubType::HeaderStaticData:
         default:
            throw GeneralException(
               "Unknown header record type: "
               + std::to_string(static_cast<int>(headerRecord.getSubType())));
      }
   }
   catch (const std::exception& ex)
   {
      throw GeneralException(
         "Exception occurred while encoding header record: " + std::string(ex.what()));
   }
