bool SatellitePolynomialCache::process(
   const GnssKey& key,
   const std::shared_ptr<const PositionPolynomial>& input)
{
   // Get or create the node associated with the key
   Node& node = m_data[key];

   if (!node.empty())
   {
      if (input->data.timespanHalfValidity < TIME_COMPARISON_EPSILON)
      {
         Logger::warn(
            FacilityCode::SatPosPolyCache,
            "Invalid input: non-positive timespanHalfValidity");
         return false;
      }

      const auto& lastInput = node.back();

      // Reject if new input time is less than the last item's time.
      if (compareGreater(lastInput->time, input->time))
      {
         return false;
      }

      // If equal time and same discontinuity, replace the last item.
      const bool sameTime = compareEqual(lastInput->time, input->time);
      const bool sameDiscontinuity
         = lastInput->data.discontinuityCounter == input->data.discontinuityCounter;

      if (sameTime && sameDiscontinuity)
      {
         node.pop_back();
      }
      else
      {
         // New input has time greater than last item or the discontinuityCounter is different ->
         // this is the expected normal flow
      }
   }

   // Push the data and prune stale entries by time window
   node.push_back(input);
   applyTimeWindowFilter(key);
   return true;
}

