void RuntimeConfig::processInputFlag(const std::vector<std::string>& optArgs)
{
   if (optArgs.empty())
   {
      throw InvalidArgumentsException("No input path provided for --input/-i flag");
   }

   const std::string& inputPath = optArgs.at(0);
   const std::filesystem::path inputFsPath{inputPath};

   s_convert.enabled = true;
   s_version.enabled = false;
   s_help.enabled = false;

   if (inputFsPath.has_extension())
   {
      // Treat as single file.
      s_convert.inputFilePath = inputPath;
      s_convert.inputFolderPath.clear();

      std::string ext = inputFsPath.extension().string();
      static_cast<void>(std::transform(ext.begin(), ext.end(), ext.begin(), [](const char chr) {
         return std::tolower(chr, std::locale::classic());
      }));

      if (ext == XML_EXTENSION)
      {
         s_convert.direction = Direction::ToHlf;
      }
      else if (ext == HLF_EXTENSION)
      {
         s_convert.direction = Direction::ToXml;
      }
      else
      {
         throw InvalidArgumentsException("Unrecognized input file extension: " + ext);
      }
   }
   else
   {
      // Folder path for batch conversion.
      s_convert.inputFolderPath = inputPath;
      s_convert.inputFilePath.clear();
   }
}

